const excludedText = "script,style,noscript,[data-no-translate],.article-body,.home-hero h1,.home-hero .lead,.program-page,.team-card h3,.team-card p,.contact-info-row dd,.accommodation-description,.about-profile-intro,.about-profile-detail p,.faq summary,.faq p,.applicant-data-table td,.news-cell-title strong,.gallery-cell-title strong,.applicant-name-cell strong,.article h2";
const translatedAttributes = ["placeholder", "aria-label", "title", "alt", "value", "content"] as const;

function createTranslator(english: boolean) {
  const replacements = new Map<string, string>();
  for (const [id, en] of pairs) replacements.set(maskBrandNames(english ? id : en).toLocaleLowerCase(), maskBrandNames(english ? en : id));
  const alternatives = [...replacements.keys()].sort((a, b) => b.length - a.length)
    .map(value => value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  const pattern = new RegExp(`(^|[^\\p{L}\\p{N}])(${alternatives.join("|")})(?=$|[^\\p{L}\\p{N}])`, "giu");
  return (input: string) => restoreBrandNames(maskBrandNames(input)
    .replace(pattern, (_match, prefix: string, phrase: string) => `${prefix}${replacements.get(phrase.toLocaleLowerCase()) || phrase}`));
}

let englishTranslator: ((value: string) => string) | undefined;
let indonesianTranslator: ((value: string) => string) | undefined;
function getTranslator(english: boolean) {
  if (english) return englishTranslator ||= createTranslator(true);
  return indonesianTranslator ||= createTranslator(false);
}

function translateAttributes(element: Element, translate: (value: string) => string) {
  if (element.closest(excludedText)) return;
  for (const name of translatedAttributes) {
    if (name === "alt" && element.matches(".gallery-tile img,.lightbox-stage img,.team-card img,.album-card-image img,.article-body img")) continue;
    const original = element.getAttribute(name);
    if (!original) continue;
    const translated = translate(original);
    if (translated !== original) element.setAttribute(name, translated);
  }
}

function translateSubtree(root: Node, translate: (value: string) => string) {
  if (root instanceof Element) {
    if (root.matches(excludedText)) return;
    translateAttributes(root, translate);
  }
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
  let current: Node | null = root.nodeType === Node.TEXT_NODE ? root : null;
  while (current || walker.nextNode()) {
    const node = current || walker.currentNode;
    current = null;
    if (node.nodeType === Node.TEXT_NODE) {
      const text = node as Text;
      const parent = text.parentElement;
      const previewText = parent?.closest(".admin-form .content-card p");
      const publicCardText = parent?.closest(".content-card p,.content-card h3");
      const dataCell = parent?.closest(".data-table td");
      const dataCellControl = parent?.closest(".news-cell-label,.gallery-cell-label,.applicant-cell-label,.status,a,button");
      const excluded = Boolean(parent?.closest(excludedText))
        || Boolean(publicCardText && !parent?.closest(".admin-form"))
        || Boolean(previewText && parent?.tagName !== "STRONG")
        || Boolean(dataCell && !dataCellControl);
      if (!excluded) {
        const original = text.nodeValue || "";
        const translated = translate(original);
        if (translated !== original) text.nodeValue = translated;
      }
    } else if (node instanceof Element) {
      translateAttributes(node, translate);
    }
  }
}

function translateDocument(english: boolean) {
  const translate = getTranslator(english);
  document.title = translate(document.title);
  translateSubtree(document.body, translate);
  document.head.querySelectorAll("meta[name=description],meta[property='og:title'],meta[property='og:description']")
    .forEach(element => translateAttributes(element, translate));
}

export function LanguageRuntime() {
  useEffect(() => {
    let english = localStorage.getItem("chp-language") === "en";
    document.documentElement.lang = english ? "en" : "id";
    document.documentElement.dataset.language = english ? "en" : "id";
    translateDocument(english);
    let queued = false;
    let changedNodes = new Set<Node>();
    let frame = 0;
    const observer = new MutationObserver(records => {
      for (const record of records) {
        if (record.type === "characterData") changedNodes.add(record.target);
        for (const node of record.addedNodes) changedNodes.add(node);
      }
      if (queued || changedNodes.size === 0) return;
      queued = true;
      frame = requestAnimationFrame(() => {
        queued = false;
        const translate = getTranslator(english);
        for (const node of changedNodes) translateSubtree(node, translate);
        changedNodes = new Set<Node>();
      });
    });
    observer.observe(document.documentElement, { childList: true, characterData: true, subtree: true });
    const nativeAlert = window.alert;
    const nativeConfirm = window.confirm;
    const nativePrompt = window.prompt;
    const localizeDialog = (message: string) => {
      const protectedText: string[] = [];
      const masked = message.replace(/"([^"]*)"/g, (_match, value: string) => {
        const token = `__KEEP_TITLE_${protectedText.length}__`;
        protectedText.push(value);
        return `"${token}"`;
      });
      let result = getTranslator(true)(masked);
      protectedText.forEach((value, index) => { result = result.replace(`__KEEP_TITLE_${index}__`, value); });
      return result;
    };
    if (location.pathname.startsWith("/admin")) {
      window.alert = message => nativeAlert.call(window, english ? localizeDialog(message || "") : message);
      window.confirm = message => nativeConfirm.call(window, english ? localizeDialog(message || "") : message);
      window.prompt = (message, defaultValue) => nativePrompt.call(window, english ? localizeDialog(message || "") : message, defaultValue);
    }
    const change = (event: Event) => {
      english = (event as CustomEvent<"id" | "en">).detail === "en";
      translateDocument(english);
    };
    window.addEventListener("chp-language-change", change);
    return () => {
      observer.disconnect();
      cancelAnimationFrame(frame);
      window.removeEventListener("chp-language-change", change);
      if (location.pathname.startsWith("/admin")) { window.alert = nativeAlert; window.confirm = nativeConfirm; window.prompt = nativePrompt; }
    };
  }, []);
  return null;
}

export function useEnglishLanguage() {
  const [english, setEnglish] = useState(false);
  useEffect(() => {
    const sync = () => setEnglish(document.documentElement.dataset.language
      ? document.documentElement.dataset.language === "en"
      : localStorage.getItem("chp-language") === "en");
    sync();
    window.addEventListener("chp-language-change", sync);
    return () => window.removeEventListener("chp-language-change", sync);
  }, []);
  return english;
}

export function LocalizedText({ id, en, as = "span", className }: { id: string; en?: string | null; as?: ElementType; className?: string }) {
  const english = useEnglishLanguage();
  const value = english ? en?.trim() || getTranslator(true)(id) : id;
  return createElement(as, { className, "data-no-translate": true }, english ? preserveBrandNames(value) : id);
}

export function adminText(indonesian: string, english: string) {
  return typeof document !== "undefined" && document.documentElement.dataset.language === "en" ? english : indonesian;
}
